//流水灯：T0 方式1 定时 50 ms，查询方式累计 20 次实现 1 s
#include "reg51.h"
void delay1s ( )
{
    unsigned char i;
    for ( i=0;i<20;i++ )          //20 × 50 ms = 1 s
    {
        TH0= ( 65536-50000 ) /256;   //T0 初值高 8 位
        TL0= ( 65536-50000 ) %256;   //T0 初值低 8 位
        TR0=1;                       //启动 T0
        while ( !TF0 ) ;             //查询是否溢出（50 ms 到）
        TF0=0;                       //查询方式下必须由软件清零
    }
}
void main ( )
{
    unsigned char led=0xfe;       //1111 1110B，最低位灯亮
    TMOD=0x01;                    //T0 为工作方式 1
    while ( 1 )
    {
        P1=led;                   //输出当前状态
        delay1s ( ) ;             //间隔 1 s
        led= ( led<<1 ) | 0x01;   //左移一位，末位补 1（熄灭）
        if ( led==0xff ) led=0xfe; //8 个灯轮完一遍后重新开始
    }
}
要点：TMOD=0x01 表示 T0 软件启动、定时、方式 1；初值 X=65 536−50 000=15 536；用 while(!TF0) 查询溢出，查询方式下 TF0 必须由软件清零；P1 口输出低电平点亮对应 LED，0xFE→0xFD→0xFB…→0x7F 依次左移即形成流水效果。
